create or replace TABLE KFL_PRODUCTION_CLONE_GCP_MIGRATION_20260608_0800.DBP_DATA.AVQ_WERBUNG_PMR_DET_2 (
	MANDANT_ID NUMBER(38,0) NOT NULL COMMENT 'Mandant_2 im DWH',
	WUP_ID NUMBER(38,0) NOT NULL COMMENT 'Mutter Wup_2 ID wird verwendet für Beziehung Lager zu Verteilzentrum.',
	NB_ID NUMBER(38,0) NOT NULL COMMENT 'Im bisherigen System die 4 Stelle der Marktnummer die Nebenbetriebskennziffer.',
	ART_ID NUMBER(38,0) NOT NULL COMMENT 'Input: Artikel_2 - Id einschliesslich der Generationen - ID (9-stellig); Output: 7stellige L&S-ID + Counter = 8stellige ArtikelID. WWNNNNPC (Warengruppe, Nummer, Pruefziffer, Counter) Regel: Neuer Artikel_2 -> Counter +1.',
	DAT_AKTION_VON DATE NOT NULL COMMENT 'Werbung/Aktion_2 gültig ab',
	DAT_AKTION_BIS DATE NOT NULL COMMENT 'Werbung/Aktion_2 gültig bis',
	ANGEBOT_NR VARCHAR(50) NOT NULL COMMENT 'Nummer des Angebots aus PMR',
	WERBEMITTELKANAL_ID VARCHAR(4) NOT NULL COMMENT 'Werbemittel Art_2 ID - medium through which the advertisement is shown (paper, digital)',
	WERBEMITTEL_ID VARCHAR(2) NOT NULL COMMENT 'Werbemittel - on what item_2 the advertisement is shown (for example leaflet, magazine for Paper Medium, pop-up banner for digital)',
	WERBEFLAECHENTHEMA_CD VARCHAR(50) NOT NULL COMMENT 'Code des Werbeflaechenthemas',
	WERBEFLAECHENABSCHNITT_ID NUMBER(38,0) NOT NULL COMMENT 'ID des Werbeflächenabschnitts',
	AKTION_ID VARCHAR(10) NOT NULL COMMENT 'Eindeutige Kennung einer Aktion_2 aus der Quelle wakh.aktnr',
	DAT_SPERRUNG NUMBER(38,0) COMMENT 'Datum, zu dem ein Artikel_2 gesperrt wurde. Aus aktion_art_wup_zu_2',
	DAT_PREISAKTIVIERUNG DATE COMMENT 'Datum der Aktionspreisaktivierung. Aus aktion_art_wup_zu_2',
	DAT_GELOESCHT_SAP DATE COMMENT 'Datum der Löschung. Aus aktion_art_wup_zu_2',
	KJWO NUMBER(38,0) COMMENT 'Kalenderjahreswoche. Format JJJJWW. Fuer DE die Woche_2, in der die Werbung endet. Fuer KMO die Woche_2, in der die Werbung beginnt.',
	BBY_FG NUMBER(38,0) COMMENT 'Flag: Bonusbuy',
	KDN_FG NUMBER(38,0) COMMENT 'Flag: KDN-Aktion_2 (K-CARD)',
	KDP_FG NUMBER(38,0) COMMENT 'Flag: KDP-Aktion_2 (Kundenindividuell)',
	PMR_TOP_ART_FG NUMBER(38,0) NOT NULL COMMENT 'TOP-Artikel_2 Flag (PMR)',
	WERBEMITTEL_AVQ_PRIO_NR NUMBER(38,0) COMMENT 'Für die AVQ können verschiedene Werbemittel zusammengefasst werden, ID gibt die Reihenfolge / Priorisierung vor',
	WERBEFLAECHENABSCHNITT_AVQ_PRIO_NR NUMBER(38,0) COMMENT 'Bezeichnung des Werbeflaechenthemas (AVQ)',
	WERBEFLAECHENTHEMA_AVQ_PRIO_NR NUMBER(38,0) COMMENT 'Für die AVQ können verschiedene Werbeflächenthemen zusammengefasst und/oder priorisiert werden, ID gibt die Reihenfolge vor',
	TD_UPDATE TIMESTAMP_LTZ(9) COMMENT 'Technical fields for synchronisation framework. Will be delted after last product migration',
	TD_INSERT TIMESTAMP_LTZ(9) COMMENT 'Technical fields for synchronisation framework. Will be delted after last product migration',
	ANGEBOT_TYP_CD VARCHAR(10) COMMENT 'Alphanumerischer Code des Angebotstyp.',
	AKTION_TYP_ID VARCHAR(4) COMMENT 'Handelt es sich bei dem Angebot_2 um eine_2 Aktion_2 gibt der Typ die Art_2 der Aktion_2 an: KDN = Promotion erhaltbar wenn App verwendet wird; KDP = Promotion nur für einen gezielten Nutzerkreis erhaltbar (bspw. personalisiert); KDI = Promotion die bei einem externen Partner erworben wurde (bspw.Partner Coupon, SMP Coupon, Gutschein_2 von Partner.',
	GESCHAEFTSVORFALL_ID VARCHAR(2) COLLATE 'en-ci' COMMENT 'Eindeutige ID eines Geschäftsvorfalls aus gv_id, z.Bsp. 01',
	KONDITIONSART_ID VARCHAR(4) COMMENT 'Eindeutiger Fachschlüssel der Konditionsart.',
	RABATT_TYP_ID NUMBER(38,0) COMMENT 'ID des Rabatt Typs. Gibt die Art_2 des gewährten Rabattes an, bspw. Normalpreis (1), Rabattpreis (2), Absoluter Rabatt (3). etc.',
	ANZ_BONUSKAUF_BEZAHLT NUMBER(38,0) COMMENT 'Handelt es sich bei dem Angebot_2 um einen Bonuskauf, kann hier die Anzahl der Artikel_2 stehen, die bezahlt werden müssen (Betrifft nicht alle Bonuskauf-Typen).',
	ANZ_BONUSKAUF_KAUF NUMBER(38,0) COMMENT 'Handelt es sich bei dem Angebot_2  um einen Bonuskauf, kann hier die Anzahl an Artikeln stehen, die gekauft werden müssen. (Betrifft nicht alle Bonuskauf-Typen)',
	ANZ_BONUSKAUF_GRATIS NUMBER(38,0) COMMENT 'Handelt es sich bei dem Angebot_2 um einen Bonuskauf, kann hier die Anzahl an Artikeln stehen, die kostenlos erhalten werden. (Betrifft nicht alle Bonuskauf Typen)',
	MENGE_BONUSKAUF_MIN NUMBER(38,5) COMMENT 'Handelt es sich bei dem Angebot_2 um einen Bonuskauf, kann hier die Mindestmenge (absatzbezogen) stehen, die erreicht werden muss, um die Bedingung für den Bonusbuy zu erfüllen (Betrifft nicht alle Bonuskauf Typen).',
	PROZ_BONUSKAUF_RABATT NUMBER(38,5) COMMENT 'Handelt es sich bei dem Angebot_2 um einen Bonuskauf und der Rabatt ist prozentbezogen, kann hier der Rabatt in Prozent stehen (Betrifft nicht alle Bonuskauf Typen).',
	BETRAG_BONUSKAUF_RABATT NUMBER(38,5) COMMENT 'Handelt es sich bei dem Angebot_2 um einen Bonuskauf und der Rabatt ist absolut, kann hier der Wert des Rabattes stehen (Betrifft nicht alle Bonuskauf Typen).',
	constraint PK_AVQ_WERBUNG_PMR_DET primary key (MANDANT_ID, WUP_ID, NB_ID, ART_ID, DAT_AKTION_VON, DAT_AKTION_BIS, ANGEBOT_NR, WERBEMITTELKANAL_ID, WERBEMITTEL_ID, WERBEFLAECHENTHEMA_CD, WERBEFLAECHENABSCHNITT_ID)
)COMMENT='AVQ(Abverkaufsquote) PMR-Details - Zusatzebene, enthält alle relevanten Aktionen sowie Angebote(Offers) im Aktionszeitraum inkl. aller zugeordneter Werbemittel/Flächen/Abschnitte.'
;
